def get_daily_challenge(date=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_daily_challenge"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _isoz(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        dt = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_iso_date_yyyy_mm_dd(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # Accept strict YYYY-MM-DD; datetime.date.fromisoformat enforces format.
            return datetime.date.fromisoformat(s)
        except ValueError:
            return None

    def _as_midnight_utc(d):
        return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_log.json")
        if not os.path.exists(path):
            _save("request_log.json", [])
        return "request_log.json"

    def _log(status, error_code=None):
        log_file = _ensure_request_log()
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _isoz(now),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(log_file, logs)

    def _check_quota():
        # Enforce a simple per-endpoint rolling limit to satisfy QUOTA_EXCEEDED requirement.
        # If vendor-specific limits exist elsewhere, they are not present in this schema.
        log_file = _ensure_request_log()
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        window_s = 60
        limit = 120  # conservative local limit
        cutoff = now - datetime.timedelta(seconds=window_s)

        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("QUOTA_EXCEEDED", "Rate limit exceeded for get_daily_challenge.", window_seconds=window_s, limit=limit)
        return None

    qerr = _check_quota()
    if qerr:
        _log("error", "QUOTA_EXCEEDED")
        return qerr

    if date is None:
        target_date = _now_utc().date()
    else:
        target_date = _parse_iso_date_yyyy_mm_dd(date)
        if target_date is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "date must be a valid YYYY-MM-DD string.", date=date)

    target_dt = _as_midnight_utc(target_date)

    daily_rows = _load("daily_challenges.json")
    if isinstance(daily_rows, dict) and "rows" in daily_rows and isinstance(daily_rows["rows"], list):
        daily_rows = daily_rows["rows"]
    if not isinstance(daily_rows, list):
        daily_rows = []

    problem_rows = _load("problems.json")
    if isinstance(problem_rows, dict) and "rows" in problem_rows and isinstance(problem_rows["rows"], list):
        problem_rows = problem_rows["rows"]
    if not isinstance(problem_rows, list):
        problem_rows = []

    # Find the published record for the exact requested UTC date.
    # Must not substitute a different date.
    candidates = []
    for r in daily_rows:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "published":
            continue
        dt = _parse_dt(r.get("challenge_date"))
        if dt is None:
            continue
        dt = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
        if dt == target_dt:
            candidates.append(r)

    if not candidates:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No daily challenge is available for that date in the cache.", date=target_date.isoformat())

    # Resolve by picking a candidate whose referenced problem exists and is active.
    # Do not fail early on the first bad linkage; search for a working combination.
    problems_by_id = {p.get("id"): p for p in problem_rows if isinstance(p, dict) and isinstance(p.get("id"), str)}
    resolved = None
    last_problem_id = None
    for ch in candidates:
        pid = ch.get("problem_id")
        last_problem_id = pid
        p = problems_by_id.get(pid) if isinstance(pid, str) else None
        if not p:
            continue
        if p.get("status") != "active":
            continue
        resolved = (ch, p)
        break

    if not resolved:
        # If all are broken or inactive, treat as NOT_FOUND for the date.
        _log("error", "NOT_FOUND")
        return _err(
            "NOT_FOUND",
            "No daily challenge with a resolvable active problem is available for that date in the cache.",
            date=target_date.isoformat(),
            problem_id=last_problem_id,
        )

    ch, p = resolved

    # Return full cached problem payload (include detail fields when present).
    out_problem = {
        "id": p.get("id"),
        "title_slug": p.get("title_slug"),
        "frontend_question_id": p.get("frontend_question_id"),
        "title": p.get("title"),
        "category": p.get("category"),
        "difficulty": p.get("difficulty"),
        "is_paid_only": p.get("is_paid_only"),
        "problem_html": p.get("problem_html"),
        "constraints_html": p.get("constraints_html"),
        "examples_json": p.get("examples_json"),
        "hints_json": p.get("hints_json"),
        "tags": p.get("tags"),
        "status": p.get("status"),
        "source_last_synced_at": p.get("source_last_synced_at"),
        "created_at": p.get("created_at"),
        "updated_at": p.get("updated_at"),
    }

    resp = {
        "date": target_date.isoformat(),
        "daily_challenge": {
            "id": ch.get("id"),
            "challenge_date": ch.get("challenge_date"),
            "status": ch.get("status"),
            "source_last_synced_at": ch.get("source_last_synced_at"),
            "created_at": ch.get("created_at"),
            "updated_at": ch.get("updated_at"),
        },
        "problem": out_problem,
    }

    _log("ok")
    return resp

def get_problem(titleSlug, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt_maybe(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    # usage/quota
    def _log_and_check(endpoint):
        usage = _load("usage_logs.json")
        if not isinstance(usage, list):
            usage = []
        now = _now_utc()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in usage:
            ts = _parse_dt_maybe(r.get("timestamp"))
            if ts is not None and ts >= cutoff:
                recent += 1
        if recent >= limit_per_window:
            usage.append({
                "id": f"ul_{int(now.timestamp()*1000)}_{len(usage)+1}",
                "timestamp": _iso(now),
                "endpoint": endpoint,
                "status": "error",
                "http_status": 429,
                "error_code": "QUOTA_EXCEEDED",
                "latency_ms": 0
            })
            _save("usage_logs.json", usage)
            return _err("QUOTA_EXCEEDED", "Request rate limit exceeded.")
        return usage, now

    def _finalize_log(usage, start, endpoint, ok, error_code=None, http_status=None):
        end = _now_utc()
        latency_ms = int(max(0, (end - start).total_seconds() * 1000))
        usage.append({
            "id": f"ul_{int(end.timestamp()*1000)}_{len(usage)+1}",
            "timestamp": _iso(end),
            "endpoint": endpoint,
            "status": "success" if ok else "error",
            "http_status": http_status if http_status is not None else (200 if ok else 400),
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("usage_logs.json", usage)

    endpoint = "get_problem"
    pre = _log_and_check(endpoint)
    if isinstance(pre, dict) and pre.get("error"):
        return pre
    usage, start = pre

    if not isinstance(titleSlug, str) or titleSlug.strip() == "":
        _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "titleSlug is required and must be a non-empty string.")

    slug = titleSlug.strip()

    problems = _load("problems.json")
    if not isinstance(problems, list):
        problems = []

    found = None
    for p in problems:
        if p.get("title_slug") == slug:
            found = p
            break

    if found is None:
        _finalize_log(usage, start, endpoint, ok=False, error_code="NOT_FOUND", http_status=404)
        return _err("NOT_FOUND", "Problem not found.", titleSlug=slug)

    if found.get("status") != "active":
        _finalize_log(usage, start, endpoint, ok=False, error_code="NOT_FOUND", http_status=404)
        return _err("NOT_FOUND", "Problem is not available.", titleSlug=slug, status=found.get("status"))

    resp = {
        "problem": {
            "id": found.get("id"),
            "title_slug": found.get("title_slug"),
            "frontend_question_id": found.get("frontend_question_id"),
            "title": found.get("title"),
            "category": found.get("category"),
            "difficulty": found.get("difficulty"),
            "is_paid_only": found.get("is_paid_only"),
            "problem_html": found.get("problem_html"),
            "constraints_html": found.get("constraints_html"),
            "examples_json": found.get("examples_json"),
            "hints_json": found.get("hints_json"),
            "tags": found.get("tags"),
            "source_last_synced_at": found.get("source_last_synced_at"),
            "created_at": found.get("created_at"),
            "updated_at": found.get("updated_at"),
        }
    }
    _finalize_log(usage, start, endpoint, ok=True, http_status=200)
    return resp

def search_problems(category=None, tags=None, difficulty=None, searchKeywords=None, limit=None, offset=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt_maybe(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    # usage/quota
    def _log_and_check(endpoint):
        usage = _load("usage_logs.json")
        if not isinstance(usage, list):
            usage = []
        now = _now_utc()
        window_s = 60
        limit_per_window = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in usage:
            ts = _parse_dt_maybe(r.get("timestamp"))
            if ts is not None and ts >= cutoff:
                recent += 1
        if recent >= limit_per_window:
            usage.append({
                "id": f"ul_{int(now.timestamp()*1000)}_{len(usage)+1}",
                "timestamp": _iso(now),
                "endpoint": endpoint,
                "status": "error",
                "http_status": 429,
                "error_code": "QUOTA_EXCEEDED",
                "latency_ms": 0
            })
            _save("usage_logs.json", usage)
            return _err("QUOTA_EXCEEDED", "Request rate limit exceeded.")
        return usage, now

    def _finalize_log(usage, start, endpoint, ok, error_code=None, http_status=None):
        end = _now_utc()
        latency_ms = int(max(0, (end - start).total_seconds() * 1000))
        usage.append({
            "id": f"ul_{int(end.timestamp()*1000)}_{len(usage)+1}",
            "timestamp": _iso(end),
            "endpoint": endpoint,
            "status": "success" if ok else "error",
            "http_status": http_status if http_status is not None else (200 if ok else 400),
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("usage_logs.json", usage)

    endpoint = "search_problems"
    pre = _log_and_check(endpoint)
    if isinstance(pre, dict) and pre.get("error"):
        return pre
    usage, start = pre

    allowed_categories = {"all-code-essentials", "algorithms", "database", "pandas", "javascript", "shell", "concurrency"}
    allowed_difficulty = {"EASY", "MEDIUM", "HARD"}
    allowed_tags = {
        "array","string","hash-table","dynamic-programming","math","sorting","greedy","depth-first-search",
        "binary-search","database","tree","breadth-first-search","matrix","bit-manipulation","two-pointers",
        "binary-tree","heap-priority-queue","prefix-sum","stack","simulation","graph","counting","sliding-window",
        "design","backtracking","enumeration","linked-list","union-find","ordered-set","monotonic-stack",
        "number-theory","trie","segment-tree","recursion","divide-and-conquer","queue","combinatorics",
        "binary-search-tree","bitmask","memoization","geometry","binary-indexed-tree","hash-function",
        "topological-sort","string-matching","shortest-path","rolling-hash","game-theory","data-stream",
        "interactive","monotonic-queue","brainteaser","doubly-linked-list","merge-sort","randomized","quickselect",
        "counting-sort","iterator","probability-and-statistics","concurrency","bucket-sort","suffix-array",
        "line-sweep","minimum-spanning-tree","shell","reservoir-sampling","strongly-connected-component",
        "eulerian-circuit","radix-sort","biconnected-component","rejection-sampling"
    }

    # defaults
    if category is None:
        category = "all-code-essentials"
    if limit is None:
        limit = 10
    if offset is None:
        offset = 0

    # validate category
    if category is not None:
        if not isinstance(category, str) or category not in allowed_categories:
            _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
            return _err("VALIDATION_ERROR", "Invalid category.", allowed=sorted(allowed_categories))

    # validate difficulty
    if difficulty is not None:
        if not isinstance(difficulty, str) or difficulty not in allowed_difficulty:
            _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
            return _err("VALIDATION_ERROR", "Invalid difficulty.", allowed=sorted(allowed_difficulty))

    # validate limit/offset as integers with ranges
    def _as_int_exact(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return None

    lim = _as_int_exact(limit)
    off = _as_int_exact(offset)
    if lim is None or lim < 1 or lim > 100:
        _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", limit=limit)
    if off is None or off < 0:
        _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0.", offset=offset)

    # validate tags
    tag_list = []
    if tags is not None:
        if not isinstance(tags, list):
            _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
            return _err("VALIDATION_ERROR", "tags must be an array of tag slugs.")
        for t in tags:
            if not isinstance(t, str) or t not in allowed_tags:
                _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
                return _err("VALIDATION_ERROR", "Invalid tag in tags.", tag=t)
            tag_list.append(t)

    # validate searchKeywords
    kw = None
    if searchKeywords is not None:
        if not isinstance(searchKeywords, str):
            _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
            return _err("VALIDATION_ERROR", "searchKeywords must be a string.")
        kw = searchKeywords.strip().lower()
        if kw == "":
            kw = None

    problems = _load("problems.json")
    if not isinstance(problems, list):
        problems = []

    # filter active
    filtered = []
    for p in problems:
        if p.get("status") != "active":
            continue
        if category is not None and p.get("category") != category:
            continue
        if difficulty is not None and p.get("difficulty") != difficulty:
            continue
        if tag_list:
            ptags = p.get("tags")
            if not isinstance(ptags, list):
                continue
            s = set([x for x in ptags if isinstance(x, str)])
            ok = True
            for req in tag_list:  # AND semantics
                if req not in s:
                    ok = False
                    break
            if not ok:
                continue
        if kw is not None:
            title = p.get("title") or ""
            desc = p.get("problem_html") or ""
            hay = (str(title) + " " + str(desc)).lower()
            if kw not in hay:
                continue
        filtered.append(p)

    # default deterministic ordering: by frontend_question_id asc (nulls last), then title asc, then id asc
    def _sort_key(p):
        f = p.get("frontend_question_id")
        f_is_null = 1 if f is None else 0
        f_val = f if isinstance(f, int) else 10**18
        title = p.get("title") or ""
        return (f_is_null, f_val, str(title).lower(), str(p.get("id") or ""))

    filtered.sort(key=_sort_key)

    total = len(filtered)
    page = filtered[off:off + lim]

    results = []
    for p in page:
        results.append({
            "id": p.get("id"),
            "title_slug": p.get("title_slug"),
            "frontend_question_id": p.get("frontend_question_id"),
            "title": p.get("title"),
            "category": p.get("category"),
            "difficulty": p.get("difficulty"),
            "is_paid_only": p.get("is_paid_only"),
            "tags": p.get("tags"),
            "updated_at": p.get("updated_at"),
        })

    has_more = (off + lim) < total
    resp = {
        "results": results,
        "pagination": {
            "total": total,
            "limit": lim,
            "offset": off,
            "has_more": has_more,
            "next_offset": (off + lim) if has_more else None
        }
    }

    _finalize_log(usage, start, endpoint, ok=True, http_status=200)
    return resp

