            })
            _save("usage_logs.json", usage)
            return _err("QUOTA_EXCEEDED", "Request rate limit exceeded.")
        return usage, now

    def _finalize_log(usage, start, endpoint, ok, error_code=None, http_status=None):
        end = _now_utc()
        latency_ms = int(max(0, (end - start).total_seconds() * 1000))
        usage.append({
            "id": f"ul_{int(end.timestamp()*1000)}_{len(usage)+1}",
            "timestamp": _iso(end),
            "endpoint": endpoint,
            "status": "success" if ok else "error",
            "http_status": http_status if http_status is not None else (200 if ok else 400),
            "error_code": error_code,
            "latency_ms": latency_ms
        })
        _save("usage_logs.json", usage)

    endpoint = "get_user_profile"
    pre = _log_and_check(endpoint)
    if isinstance(pre, dict) and pre.get("error"):
        return pre
    usage, start = pre

    if not isinstance(username, str) or username.strip() == "":
        _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "username is required and must be a non-empty string.")
    uname = username.strip()
    if len(uname) < 1 or len(uname) > 64:
        _finalize_log(usage, start, endpoint, ok=False, error_code="VALIDATION_ERROR", http_status=400)
        return _err("VALIDATION_ERROR", "username length must be between 1 and 64.", length=len(uname))

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    now = _now_utc()

    # find existing by username (unique)
    idx = None
    for i, u in enumerate(users):
        if u.get("username") == uname:
            idx = i
            break

    # "upsert": if missing, create a placeholder; treat as not found until upstream sync fills it.
    if idx is None:
        new_id = f"usr_{int(now.timestamp()*1000)}_{len(users)+1}"
        row = {
            "id": new_id,
            "username": uname,
            "display_name": None,
            "avatar_url": None,
            "country": None,
            "profile_json": None,
            "stats_json": None,
            "status": "not_found",
            "source_last_synced_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        users.append(row)
        _save("users.json", users)

        _finalize_log(usage, start, endpoint, ok=False, error_code="NOT_FOUND", http_status=404)
        return _err("NOT_FOUND", "User does not exist or is not retrievable.", username=uname, status="not_found")

    row = users[idx]

    # If previously not_found/disabled, treat as not retrievable
    status = row.get("status")
    if status != "active":
        # still "upsert": update updated_at to reflect attempted refresh
        row["updated_at"] = _iso(now)
        users[idx] = row
        _save("users.json", users)

        _finalize_log(usage, start, endpoint, ok=False, error_code="NOT_FOUND", http_status=404)
        return _err("NOT_FOUND", "User does not exist or is not retrievable.", username=uname, status=status)

    resp = {
        "user": {
            "id": row.get("id"),
            "username": row.get("username"),
            "display_name": row.get("display_name"),
            "avatar_url": row.get("avatar_url"),
            "country": row.get("country"),
            "profile_json": row.get("profile_json"),
            "stats_json": row.get("stats_json"),
            "status": row.get("status"),
            "source_last_synced_at": row.get("source_last_synced_at"),
            "created_at": row.get("created_at"),
            "updated_at": row.get("updated_at"),
        }
    }

    _finalize_log(usage, start, endpoint, ok=True, http_status=200)
    return resp

def get_recent_submissions(username, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"
    try:
        # Validate
        if not isinstance(username, str) or not username.strip():
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "username is required and must be a non-empty string")
        uname = username.strip()
        if limit is None:
            limit_i = 10
        else:
            # tool schema says number, but business rules require integer
            if isinstance(limit, bool) or not isinstance(limit, (int, float)):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")
            if isinstance(limit, float) and limit != int(limit):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")
            limit_i = int(limit)
        if limit_i < 1 or limit_i > 50:
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")

        users = _load("users.json")
        user = next((u for u in users if isinstance(u, dict) and u.get("username") == uname), None)
        if not user:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "user not found")
        if user.get("status") != "active":
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "user is not active", user_status=user.get("status"))

        submissions = _load("submissions.json")
        uid = user.get("id")
        user_subs = [s for s in submissions if isinstance(s, dict) and s.get("user_id") == uid]

        if not user_subs:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "submissions unavailable")

        def _parse_dt(v):
            if isinstance(v, str):
                try:
                    return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                except Exception:
                    return None
            return None

        user_subs.sort(key=lambda s: (_parse_dt(s.get("submitted_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        items = user_subs[:limit_i]

        # Envelope
        return {
            "user": {"id": uid, "username": uname},
            "count": len(items),
            "submissions": items
        }
    finally:
        # Observable dynamics: record request
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((time.time() - t0) * 1000)
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "get_recent_submissions",
                "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
                "status": status_code,
                "latency_ms": latency_ms
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

