def get_user_contest_ranking(username, attended=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"
    try:
        if not isinstance(username, str) or not username.strip():
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "username is required and must be a non-empty string")
        uname = username.strip()
        if attended is None:
            attended_b = True
        else:
            if not isinstance(attended, bool):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "attended must be a boolean")
            attended_b = attended

        users = _load("users.json")
        user = next((u for u in users if isinstance(u, dict) and u.get("username") == uname), None)
        if not user:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "user not found")
        if user.get("status") != "active":
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "user is not active", user_status=user.get("status"))

        rankings = _load("contest_rankings.json")
        uid = user.get("id")
        row = next((r for r in rankings if isinstance(r, dict) and r.get("user_id") == uid and r.get("attended_only") == attended_b), None)
        if not row:
            status_code = "NOT_FOUND"
            return _err("NOT_FOUND", "contest data unavailable")

        # If stale/error, "may refresh". Offline store: mark refreshed to fresh if ranking_json exists.
        now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        if row.get("status") in ("stale", "error"):
            if row.get("ranking_json") is not None:
                # legal transitions per lifecycle: stale->fresh/error, error->fresh/stale
                row["status"] = "fresh"
                row["source_last_synced_at"] = now
                row["updated_at"] = now
                _save("contest_rankings.json", rankings)

        return {
            "user": {"id": uid, "username": uname},
            "attended_only": attended_b,
            "status": row.get("status"),
            "ranking": row.get("ranking_json"),
            "source_last_synced_at": row.get("source_last_synced_at"),
            "updated_at": row.get("updated_at")
        }
    finally:
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((time.time() - t0) * 1000)
            logs.append({
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "get_user_contest_ranking",
                "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
                "status": status_code,
                "latency_ms": latency_ms
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

def list_problem_solutions(questionSlug, limit=None, skip=None, orderBy=None, userInput=None, tagSlugs=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_problem_solutions"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt_maybe(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_log.json")
        if not os.path.exists(path):
            _save("request_log.json", [])
        return "request_log.json"

    def _log_and_enforce(status, error_code=None):
        log_file = _ensure_request_log()
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []

        now = _now_utc()
        window_s = 60
        limit = 120
        cutoff = now - datetime.timedelta(seconds=window_s)

        recent = 0
        for r in logs[-5000:]:
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt_maybe(r.get("timestamp"))
            if ts is not None and ts >= cutoff:
                recent += 1

        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(log_file, logs)

        if recent >= limit:
            return _err("QUOTA_EXCEEDED", f"Rate limit exceeded for {endpoint}.")
        return None

    # Validate questionSlug
    if not isinstance(questionSlug, str) or not questionSlug.strip():
        _log_and_enforce("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "questionSlug is required and must be a non-empty string.")
    slug = questionSlug.strip()

    # Validate limit/skip (accept numeric types but require integral value)
    if limit is None:
        limit_i = 10
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)):
            _log_and_enforce("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a positive integer.")
        if isinstance(limit, float) and limit != int(limit):
            _log_and_enforce("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be a positive integer.")
        limit_i = int(limit)
    if limit_i < 1 or limit_i > 50:
        _log_and_enforce("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.", limit=limit)

    if skip is None:
        skip_i = 0
    else:
        if isinstance(skip, bool) or not isinstance(skip, (int, float)):
            _log_and_enforce("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "skip must be a non-negative integer.")
        # Relax: accept 5.0 as 5
        if isinstance(skip, float) and skip != int(skip):
            _log_and_enforce("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "skip must be a non-negative integer.", skip=skip)
        skip_i = int(skip)
    if skip_i < 0:
        _log_and_enforce("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "skip must be a non-negative integer.", skip=skip)

    # Validate orderBy (relax vendor enum typo with leading space)
    if orderBy is None:
        order = "HOT"
    else:
        if not isinstance(orderBy, str):
            _log_and_enforce("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "orderBy must be a string.")
        order = orderBy.strip()
    allowed = {"HOT", "MOST_RECENT", "MOST_VOTES"}
    if order not in allowed:
        _log_and_enforce("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "orderBy must be one of: HOT, MOST_RECENT, MOST_VOTES.", orderBy=orderBy)

    # Validate tagSlugs
    if tagSlugs is None:
        tag_slugs = []
    else:
        if not isinstance(tagSlugs, list) or any((not isinstance(t, str)) for t in tagSlugs):
            _log_and_enforce("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tagSlugs must be an array of strings.")
        tag_slugs = [t.strip() for t in tagSlugs if t is not None and isinstance(t, str) and t.strip()]

    term = None
    if userInput is not None:
        if not isinstance(userInput, str):
            _log_and_enforce("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "userInput must be a string.")
        term = userInput.strip().lower()
        if term == "":
            term = None

    # Rate limit check
    quota_err = _log_and_enforce("ok")
    if quota_err:
        return quota_err

    problems = _load("problems.json")
    if not isinstance(problems, list):
        problems = []
    solutions = _load("solutions.json")
    if not isinstance(solutions, list):
        solutions = []

    # Resolve problem:
    # - Prefer title_slug == questionSlug, but datastore/audit shows callers may pass internal problems.id.
    # - Accept either (active problems only).
    problem = None
    for p in problems:
        if not isinstance(p, dict):
            continue
        if p.get("status") != "active":
            continue
        if p.get("title_slug") == slug or p.get("id") == slug:
            problem = p
            break
    if not problem:
        return _err("NOT_FOUND", "problem not found", questionSlug=slug)

    pid = problem.get("id")

    # Filter solutions by problem_id and not removed (metadata listing still ok for metadata_only/fetched)
    filtered = []
    tag_set = set([t.lower() for t in tag_slugs])
    for s in solutions:
        if not isinstance(s, dict):
            continue
        if s.get("problem_id") != pid:
            continue
        if s.get("status") == "removed":
            continue

        # tag overlap filter: at least one overlap
        if tag_set:
            stags = s.get("tags")
            if not isinstance(stags, list):
                continue
            stags_l = set([str(x).strip().lower() for x in stags if isinstance(x, str)])
            if not (stags_l & tag_set):
                continue

        # userInput search: title/author and content if fetched
        if term:
            title = (s.get("title") or "")
            author = (s.get("author_username") or "")
            hay = (title + "\n" + author).lower()
            if term not in hay:
                if s.get("status") == "fetched":
                    content = s.get("content_html") or ""
                    if term not in str(content).lower():
                        continue
                else:
                    continue

        filtered.append(s)

    # Sorting
    def _dt_key(x):
        dt = _parse_dt_maybe(x.get("published_at"))
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    def _vote_key(x):
        v = x.get("vote_count")
        if isinstance(v, bool) or v is None:
            return -1
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v == int(v):
            return int(v)
        return -1

    if order == "MOST_RECENT":
        filtered.sort(key=lambda x: (_dt_key(x), x.get("id") or ""), reverse=True)
    elif order == "MOST_VOTES":
        filtered.sort(key=lambda x: (_vote_key(x), _dt_key(x), x.get("id") or ""), reverse=True)
    else:  # HOT
        # pinned desc, votes desc, published_at desc
        def _pinned(x):
            return 1 if x.get("is_pinned") is True else 0
        filtered.sort(key=lambda x: (_pinned(x), _vote_key(x), _dt_key(x), x.get("id") or ""), reverse=True)

    total = len(filtered)
    page = filtered[skip_i: skip_i + limit_i]
    has_more = (skip_i + limit_i) < total

    # Return metadata only (no full content)
    def _to_meta(s):
        return {
            "id": s.get("id"),
            "topic_id": s.get("topic_id"),
            "problem_id": s.get("problem_id"),
            "title": s.get("title"),
            "author_username": s.get("author_username"),
            "tags": s.get("tags"),
            "vote_count": s.get("vote_count"),
            "is_pinned": s.get("is_pinned"),
            "published_at": s.get("published_at"),
            "status": s.get("status"),
            "source_last_synced_at": s.get("source_last_synced_at"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at"),
        }

    return {
        "problem": {
            "id": problem.get("id"),
            "title_slug": problem.get("title_slug"),
            "title": problem.get("title"),
            "difficulty": problem.get("difficulty"),
            "category": problem.get("category"),
        },
        "solutions": [_to_meta(s) for s in page],
        "pagination": {
            "skip": skip_i,
            "limit": limit_i,
            "total": total,
            "has_more": has_more,
            "next_skip": (skip_i + limit_i) if has_more else None,
        },
        "orderBy": order,
    }

