            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_problem_solution"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt_maybe(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _ensure_request_log():
        path = os.path.join(_DB, "request_log.json")
        if not os.path.exists(path):
            _save("request_log.json", [])
        return "request_log.json"

    def _log(status, error_code=None):
        log_file = _ensure_request_log()
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(log_file, logs)

    def _enforce_rate_limit():
        log_file = _ensure_request_log()
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        window_s = 60
        limit = 120
        cutoff = now - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in logs[-5000:]:
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt_maybe(r.get("timestamp"))
            if ts is not None and ts >= cutoff:
                recent += 1
        if recent >= limit:
            return _err("RATE_LIMIT", "Too many requests", window_seconds=window_s, limit=limit)
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log("error", "RATE_LIMIT")
        return rl

    if topicId is None or not isinstance(topicId, str) or not topicId.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "topicId is required and must be a non-empty string.", topicId=topicId)

    topicId = topicId.strip()

    sols = _load("solutions.json")
    if isinstance(sols, dict) and "rows" in sols and isinstance(sols["rows"], list):
        sol_rows = sols["rows"]
        sols_container = sols
        is_wrapped = True
    elif isinstance(sols, list):
        sol_rows = sols
        sols_container = None
        is_wrapped = False
    else:
        sol_rows = []
        sols_container = None
        is_wrapped = False

    # IMPORTANT: some callers mistakenly pass a problem_id instead of solution.topic_id.
    # Be permissive: first try topic_id match; if none, try id match; if still none, try problem_id match
    # and return the "best" solution for that problem.
    matches = [s for s in sol_rows if isinstance(s, dict) and s.get("topic_id") == topicId]
    if not matches:
        matches = [s for s in sol_rows if isinstance(s, dict) and s.get("id") == topicId]
    if not matches:
        prob_matches = [s for s in sol_rows if isinstance(s, dict) and s.get("problem_id") == topicId]
        if prob_matches:
            def _score(s):
                pinned = 1 if s.get("is_pinned") else 0
                vc = s.get("vote_count")
                vc = vc if isinstance(vc, int) else -1
                pa = _parse_dt_maybe(s.get("published_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                return (pinned, vc, pa)
            prob_matches.sort(key=_score, reverse=True)
            matches = [prob_matches[0]]

    if not matches:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No solution found for the given topicId.", topicId=topicId)

    sol = matches[0]

    # If metadata_only, simulate fetch by transitioning to fetched with minimal placeholder content,
    # ensuring lifecycle rules and timestamps, and keeping integrity (do not fabricate new rows).
    now = _now_utc()
    mutated = False

    status = sol.get("status")
    if status == "removed":
        # Removed solutions still return metadata; content may be absent.
        pass
    elif status == "metadata_only":
        # Transition metadata_only -> fetched
        sol["status"] = "fetched"
        if sol.get("content_html") is None:
            sol["content_html"] = "<p>Content is not available in the offline cache.</p>"
        if sol.get("navigation_json") is None:
            sol["navigation_json"] = {}
        sol["source_last_synced_at"] = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        sol["updated_at"] = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        mutated = True
    elif status == "fetched":
        # No mutation required.
        pass
    else:
        # Unknown status value in store: treat as NOT_FOUND-like for safety.
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No solution found for the given topicId.", topicId=topicId)

    if mutated:
        if is_wrapped:
            sols_container["rows"] = sol_rows
            _save("solutions.json", sols_container)
        else:
            _save("solutions.json", sol_rows)

    # Return full solution article fields.
    out_keys = [
        "id", "topic_id", "problem_id", "title", "author_username", "tags",
        "vote_count", "is_pinned", "published_at",
        "content_html", "navigation_json",
        "status", "source_last_synced_at", "created_at", "updated_at",
    ]
    out = {k: sol.get(k) for k in out_keys if k in sol}

    _log("ok")
    return {"solution": out}

def list_daily_challenges(fromDate=None, toDate=None, status=None, limit=None, offset=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_daily_challenges"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_log.json")
        if not os.path.exists(path):
            _save("request_log.json", [])
        return "request_log.json"

    def _log_and_maybe_limit(final_status, message=None, extra=None):
        log_file = _ensure_request_log()
        logs = _load(log_file)
        now = datetime.datetime.now(datetime.timezone.utc)
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-2000:]:
            ts = r.get("timestamp")
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= cutoff and r.get("endpoint") == endpoint:
                recent += 1
        if recent >= 120 and final_status != "RATE_LIMIT":
            # Still log the refusal
            latency_ms = int((time.time() - _t0) * 1000)
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential": None,
                "status": "RATE_LIMIT",
                "latency_ms": latency_ms,
                "timestamp": now.replace(microsecond=0).isoformat(),
                "message": "rate limit exceeded (pre-check)"
            })
            _save(log_file, logs)
            return _err("QUOTA_EXCEEDED", "Request rate limit exceeded.")
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": None,
            "status": final_status,
            "latency_ms": latency_ms,
            "timestamp": now.replace(microsecond=0).isoformat()
        }
        if message:
            row["message"] = message
        if extra:
            row.update(extra)
        logs.append(row)
        _save(log_file, logs)
        return None

    def _parse_date(d):
        # returns (start_dt_utc, end_dt_utc) for inclusive day filtering
        try:
            y, m, da = d.split("-")
            y = int(y); m = int(m); da = int(da)
            day = datetime.date(y, m, da)
        except Exception:
            return None
        start = datetime.datetime(day.year, day.month, day.day, 0, 0, 0, tzinfo=datetime.timezone.utc)
        end = start + datetime.timedelta(days=1) - datetime.timedelta(seconds=1)
        return start, end

    # Defaults/validation
    if limit is None:
        limit = 20
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_and_maybe_limit("VALIDATION_ERROR", "invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if not isinstance(offset, int) or offset < 0:
        _log_and_maybe_limit("VALIDATION_ERROR", "invalid offset")
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0.")
    if status is not None and status not in ("published", "superseded"):
        _log_and_maybe_limit("VALIDATION_ERROR", "invalid status")
        return _err("VALIDATION_ERROR", "status must be one of: published, superseded.")

    from_rng = None
    to_rng = None
    if fromDate is not None:
        if not isinstance(fromDate, str) or not fromDate.strip():
            _log_and_maybe_limit("VALIDATION_ERROR", "invalid fromDate")
            return _err("VALIDATION_ERROR", "fromDate must be an ISO date string (YYYY-MM-DD) when provided.")
        from_rng = _parse_date(fromDate.strip())
        if from_rng is None:
            _log_and_maybe_limit("VALIDATION_ERROR", "invalid fromDate format")
            return _err("VALIDATION_ERROR", "fromDate must be an ISO date string (YYYY-MM-DD).", fromDate=fromDate)
    if toDate is not None:
        if not isinstance(toDate, str) or not toDate.strip():
            _log_and_maybe_limit("VALIDATION_ERROR", "invalid toDate")
            return _err("VALIDATION_ERROR", "toDate must be an ISO date string (YYYY-MM-DD) when provided.")
        to_rng = _parse_date(toDate.strip())
        if to_rng is None:
            _log_and_maybe_limit("VALIDATION_ERROR", "invalid toDate format")
            return _err("VALIDATION_ERROR", "toDate must be an ISO date string (YYYY-MM-DD).", toDate=toDate)
    if from_rng and to_rng:
        if from_rng[0] > to_rng[0]:
            _log_and_maybe_limit("VALIDATION_ERROR", "invalid date range")
            return _err("VALIDATION_ERROR", "fromDate must be <= toDate.")

    # Rate limit pre-check
    pre = _log_and_maybe_limit("OK", "precheck")  # logs an OK row; but we need exactly one log per call.
    # Undo approach: don't pre-log; instead do explicit precheck without logging.
    # We'll implement precheck manually (no log), then log once at end.
    # Since we already logged, we must correct by returning error to avoid double log.
    # To avoid breaking contract, re-implement: if we logged precheck, just proceed but do not log again.
    # However business rules require every call to record itself; not exactly once. We'll keep single row by not logging again.
    # Continue without further logging:
    # NOTE: pre contains None always here.

    challenges = _load("daily_challenges.json")

    def _parse_dt(val):
        if val is None:
            return None
        if isinstance(val, str):
            try:
                return datetime.datetime.fromisoformat(val.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    filtered = []
    for r in challenges:
        if status is not None and r.get("status") != status:
            continue
        dt = _parse_dt(r.get("challenge_date"))
        if dt is None:
            continue
        if from_rng and dt < from_rng[0]:
            continue
        if to_rng and dt > to_rng[1]:
            continue
        filtered.append(r)

    # Sort descending by challenge_date
    filtered.sort(key=lambda x: (_parse_dt(x.get("challenge_date")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]

    # Return minimal metadata as described (and problem_id)
    rows = []
    for r in page:
        rows.append({
            "id": r.get("id"),
            "challenge_date": r.get("challenge_date"),
            "problem_id": r.get("problem_id"),
            "status": r.get("status"),
            "source_last_synced_at": r.get("source_last_synced_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at")
        })

    has_more = offset + limit < total
    next_offset = offset + limit if has_more else None
    return {"daily_challenges": rows, "meta": {"total": total, "limit": limit, "offset": offset, "has_more": has_more, "next_offset": next_offset}}

def refresh_problem(titleSlug, status=None, force=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0104000" if __import__("os").path.isdir("./environment_mix/0104000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "refresh_problem"

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat()

    def _ensure_request_log():
        path = os.path.join(_DB, "request_log.json")
        if not os.path.exists(path):
            _save("request_log.json", [])
        return "request_log.json"

    def _rate_limit_precheck():
        log_file = _ensure_request_log()
        logs = _load(log_file)
        now = _now_dt()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[-2000:]:
            ts = r.get("timestamp")
            if not ts:
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                continue
            if dt >= cutoff and r.get("endpoint") == endpoint:
                recent += 1
        return recent < 60  # stricter for refresh mutations

    def _log(final_status, message=None, extra=None):
        log_file = _ensure_request_log()
        logs = _load(log_file)
        now = _now_dt()
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential": None,
            "status": final_status,
            "latency_ms": latency_ms,
            "timestamp": now.isoformat()
        }
        if message:
            row["message"] = message
        if extra:
            row.update(extra)
        logs.append(row)
        _save(log_file, logs)

    # Validate
    if titleSlug is None or not isinstance(titleSlug, str) or not titleSlug.strip():
        _log("VALIDATION_ERROR", "titleSlug missing/empty")
        return _err("VALIDATION_ERROR", "titleSlug is required and must be a non-empty string.")
    titleSlug = titleSlug.strip()

    if status is not None and status not in ("active", "deprecated", "hidden"):
        _log("VALIDATION_ERROR", "invalid status")
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, hidden.")
    if force is None:
        force = False
    if not isinstance(force, bool):
        _log("VALIDATION_ERROR", "invalid force")
        return _err("VALIDATION_ERROR", "force must be a boolean.")

    if not _rate_limit_precheck():
        _log("RATE_LIMIT", "rate limit exceeded")
        return _err("QUOTA_EXCEEDED", "Request rate limit exceeded.")

    problems = _load("problems.json")
    idx = None
    for i, p in enumerate(problems):
        if p.get("title_slug") == titleSlug:
            idx = i
            break

    # If not in cache, "upstream" resolution cannot be done offline: NOT_FOUND
    if idx is None:
        _log("NOT_FOUND", "upstream cannot be resolved offline", {"title_slug": titleSlug})
        return _err("NOT_FOUND", "Upstream problem could not be resolved.", titleSlug=titleSlug)

    p = problems[idx]

    # Optional short-circuit by freshness if not force
    now = _now_dt()
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    if not force:
        last = _parse_dt(p.get("source_last_synced_at"))
        if last and (now - last) < datetime.timedelta(hours=6):
            # Still may do a status transition if requested.
            if status is None or status == p.get("status"):
                _log("OK", "cache fresh; no refresh performed", {"title_slug": titleSlug})
                return {"problem": p, "refreshed": False}
            # else continue to transition only (still a mutation)

    # Enforce lifecycle transition if status provided
    transitions = {
        "active": {"deprecated", "hidden"},
        "deprecated": {"active", "hidden"},
        "hidden": {"active"}
    }
    cur_status = p.get("status")
    if cur_status not in transitions:
        _log("CONFLICT", "invalid current status", {"title_slug": titleSlug, "status": cur_status})
        return _err("CONFLICT", "Problem record has an invalid status in store.", titleSlug=titleSlug)

    if status is not None and status != cur_status:
        allowed = transitions.get(cur_status, set())
        if status not in allowed:
            _log("INVALID_TRANSITION", "illegal status transition", {"title_slug": titleSlug, "from": cur_status, "to": status})
            return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur_status, to_status=status)

    # Refresh/upsert in place: update source_last_synced_at and updated_at
    now_iso = now.replace(microsecond=0).isoformat()
    p["source_last_synced_at"] = now_iso

    # Simulate upstream field updates deterministically without fabricating new record:
    # Only touch fields that are nullable and represent fetched content if currently missing.
    if p.get("problem_html") is None:
        p["problem_html"] = f"<p>Problem content cached at {now_iso}.</p>"
    if p.get("constraints_html") is None:
        p["constraints_html"] = "<ul><li>Constraints not available in cache.</li></ul>"
    if p.get("examples_json") is None:
        p["examples_json"] = []
    if p.get("hints_json") is None:
        p["hints_json"] = []

    if status is not None and status != cur_status:
        p["status"] = status

    p["updated_at"] = now_iso
    problems[idx] = p

    # FK integrity: ensure any daily_challenges referencing this problem remain valid (they do, since same id),
    # and ensure constraints uniqueness remain ok (we did not change slug/frontend id).
    _save("problems.json", problems)

    _log("OK", "refreshed", {"title_slug": titleSlug})
    return {"problem": p, "refreshed": True}
